from dataclasses import dataclass

import pytest


@dataclass
class Rect:
    w: int
    h: int


@dataclass
class Square:
    side: int


@dataclass
class Tri:
    b: int
    h: int


Shape = Rect | Square | Tri


def area(s: Shape) -> int:
    """Area of a shape, rounded down to an int.

    Rect: w * h. Square: side * side. Tri: b * h / 2, floored.
    """
    match s:
        case Rect(w=w, h=h):
            return w * h
        case Square(side=side):
            return side * side
        case Tri(b=b, h=h):
            return b * h // 2


def test_area_rect() -> None:
    assert area(Rect(3, 4)) == 12
    assert area(Rect(1, 1)) == 1


def test_area_square() -> None:
    assert area(Square(5)) == 25
    assert area(Square(1)) == 1


def test_area_tri_even() -> None:
    assert area(Tri(4, 3)) == 6
    assert area(Tri(10, 10)) == 50


def test_area_tri_rounds_down() -> None:
    assert area(Tri(3, 3)) == 4
    assert area(Tri(1, 1)) == 0
    assert area(Tri(5, 7)) == 17


def test_area_zero() -> None:
    assert area(Rect(0, 5)) == 0
    assert area(Square(0)) == 0
    assert area(Tri(0, 9)) == 0


@pytest.mark.parametrize(
    ("shape", "expected"),
    [
        (Rect(2, 3), 6),
        (Square(4), 16),
        (Tri(6, 5), 15),
        (Tri(7, 5), 17),
    ],
)
def test_area_parametrized(shape: Shape, expected: int) -> None:
    assert area(shape) == expected
